from pathlib import Path
import json,csv,re,xml.etree.ElementTree as E,html,hashlib
R=Path.cwd();D=R/'artifacts/design/detailed';m=json.loads((D/'detailed-class-model.json').read_text());classes=m['classes'];pages=json.loads((D/'diagram-pages.json').read_text())
def writecsv(name,rows):
 with (D/name).open('w',newline='',encoding='utf-8-sig') as f:
  w=csv.DictWriter(f,fieldnames=list(rows[0]));w.writeheader();w.writerows(rows)
def link(path):return '['+Path(path).name+'](../../'+path.replace('artifacts/','',1)+')'
# Mapping uses the master template's exact three-column structure.
maprows=[]
external={'GeocodingBoundary':['IGeocodingGateway','GoogleMapsGeocodingAdapter'],'DistanceBoundary':['IDistanceGateway','GoogleMapsDistanceAdapter'],'PaymentBoundary':['IPaymentGateway','SePayPaymentAdapter','PaymentNoticeHandler'],'NotificationBoundary':['INotificationGateway','NotificationAdapter'],'OrderNotificationBoundary':['INotificationGateway','NotificationAdapter']}
realization=json.loads((D/'vopc-realization-mapping.json').read_text())
for row in realization:
 maprows.append({'Analysis Class':row['UseCase']+' / '+row['AnalysisClass'],'Design Class / Component':'; '.join(row['DesignClasses']),'Mapping Rationale':row['SelectedSolution']+'; shown together on page 1 with source/pattern tags.'})
writecsv('analysis-to-design-mapping.csv',maprows)
writecsv('state-transition-class-mapping.csv',[{'Transition ID':r['id'],'State Machine':r['page'],'Source':r['source'],'Target':r['target'],'Class':r['class'],'Contract':'IStateTransition','Use Case Scope':r['scope'],'Trigger / Guard':r['label'].replace('\n','; '),'Basis':r['basis']} for r in m['transitions']])
regs=[]
for p in m['pages']:
 for e in p['edges']:
  if e['kind']=='realization':
   a,b=e['source'],e['target'];pkg=classes[a]['package']
   if not pkg.startswith(('FreshFood-API','FreshFood.Reposistory')):continue
   lifetime='Scoped per API request / transaction' if pkg.startswith(('FreshFood-API', 'FreshFood.Reposistory')) else 'Client composition scope'
   if b=='IStateTransition':lifetime='Scoped collection; unique transition Id; reject duplicate Id at startup'
   row={'Contract':b,'Implementation':a,'Lifetime':lifetime,'Composition Root':'ApiCompositionRoot' if pkg.startswith(('FreshFood-API','FreshFood.Reposistory')) else 'Platform bootstrap','Status':'Proposed; review required'}
   if row not in regs:regs.append(row)
# Additional dependencies omitted from some use-case pages are still registered explicitly.
for a,b in [('CatalogRepository','ICatalogRepository'),('CartRepository','ICartRepository'),('ProfileRepository','IProfileRepository'),('CheckoutRepository','ICheckoutRepository'),('MyOrdersRepository','IMyOrdersRepository')]:assert any(r['Contract']==b and r['Implementation']==a for r in regs)
writecsv('dependency-injection-registrations.csv',regs)
# Map each application-service incoming call in the existing interaction catalog to an operation.
keyrules={
 'UC-C01':[('clearance','GetClearance'),('detail','GetProductDetails'),('search','Search'),('catalog','GetCatalog')],
 'UC-C03':[('remov','RemoveItem'),('change','ChangeQuantity'),('recalcul','GetCart'),('calcul','GetCart'),('load','GetCart')],
 'UC-C05':[('delet','DeleteAddress'),('recipient','SaveAddress'),('address','SaveAddress'),('update','UpdateProfile'),('email','UpdateProfile'),('load','GetProfile')],
 'UC-C06':[('authenticity','HandleVerifiedPayment'),('qr','CreatePaymentQr'),('order','PlaceOrder'),('commit','PlaceOrder'),('roll back','PlaceOrder'),('checkout','PrepareCheckout'),('delivery','PrepareCheckout'),('fee','PrepareCheckout')],
 'UC-C07':[('review','SubmitReview'),('rating','SubmitReview'),('copy','Reorder'),('cancel','CancelOrder'),('commit','CancelOrder'),('details','GetOrderDetails'),('orders','GetOrders')]}
inter=[]
for r in csv.DictReader((R/'artifacts/analysis/sequence-traceability.csv').open(encoding='utf-8-sig')):
 uc=r['UseCase']
 if uc not in m['scope'] or r['Kind']!='C' or r['Receiver']!=m['scope'][uc]['service']:continue
 text=r['Interaction'].lower();op=next((v for k,v in keyrules[uc] if k in text),None)
 assert op,(uc,text)
 inter.append({'Use Case':uc,'Analysis Page':r['Page'],'Message':r['Number'],'Source Interaction':r['Interaction'],'Design Contract':'I'+r['Receiver'],'Design Operation':op+'Async','Source Flows':r['SourceFlows'],'Status':'Proposed responsibility mapping; existing analysis sequence not silently redrawn'})
writecsv('interaction-to-design-mapping.csv',inter)
# Full class specifications expose parameters, visibility and return types using the master template guidance.
s=['# Detailed Class Specifications','','Version: 0.3 | Date: 2026-10-31 | Status: Draft for Design Review.','','The master template specifies Detailed Class Specifications under Detailed Design Class Diagrams. Each entry records responsibility/basis, package, attributes, operations, interface relationships and constraints. Class signatures are design contracts, not compiled implementation evidence.','']
for name,c in classes.items():
 s+=['## '+name,'', '**Package:** `'+c['package']+'`. **Role:** '+c['role']+'. **Scope:** '+c['scope']+'.','', '**Responsibility / basis:** '+c['basis'].replace('\n','; '),'', '| Attribute |','|---|']+['| `'+x+'` |' for x in c['attributes']]+([] if c['attributes'] else ['| No owned fields specified. |'])
 s+=['','| Operation signature including visibility, parameters and return type |','|---|']+['| `'+x+'` |' for x in c['operations']]+([] if c['operations'] else ['| Data-only classifier; no unsupported operation introduced. |'])
 outgoing=[]
 for pp in m['pages']:
  for edge in pp['edges']:
   if edge['source']==name:
    rel=(edge['target'],edge['kind'],edge['label'])
    if rel not in outgoing:outgoing.append(rel)
 if outgoing:
  s+=['','| Related classifier | Relationship | Role / usage |','|---|---|---|']
  s+=['| `'+target+'` | '+kind+' | '+label+' |' for target,kind,label in outgoing]
 origins=[r for r in realization if name in r['DesignClasses']]
 if origins:s+=['','**VOPC realization:** '+'; '.join(r['UseCase']+' / '+r['AnalysisClass']+' -> '+r['SelectedSolution'] for r in origins)+'.']
 realizations=sorted({e['target'] for p in m['pages'] for e in p['edges'] if e['source']==name and e['kind']=='realization'})
 if realizations:s+=['','**Realizes:** '+', '.join('`'+x+'`' for x in realizations)+'.']
 s+=['','**Constraints:** '+('Fields originate from the existing data catalog; private setters block direct request binding. Domain operations enforce expected state and invariant checks.' if c['role']=='entity' else 'Ordinary concrete references and native frontend lifecycle; no DI registrations, injected constructors or client DI interfaces.' if c['package'].startswith(('FreshFood-Customer-Web','FreshFood-App')) else 'Dependencies are constructor supplied at the backend; stored references are shown as navigable associations. Consumer code must not resolve services or construct repository/provider implementations.' if c['role'] in ['service','transition','controller','repository','adapter'] else 'Use only in the stated package/runtime; contract approval remains pending.'),'']
(D/'class-specifications.md').write_text('\n'.join(s),encoding='utf-8')
# Main design artifact follows the existing approved template section names.
s=['# Detailed Design Class Diagrams','','Version: 0.3 | Date: 2026-10-31 | Status: Draft for Architect / Technical Lead Review.','','## Design basis and boundaries','','Scope: UC-C01, UC-C03, UC-C05, UC-C06 and UC-C07. Inputs are the current use-case descriptions, five VOPCs, five analysis-sequence masters, package/component architecture, entity/data catalog and the 24-transition order/payment/refund model. The stakeholder explicitly requests backend-only constructor dependency injection and one class for every state transition. Detailed class diagrams contain no package frames or qualified package headers. Stored DI/collaborator references use associations; DTO and entity type usages use dependencies; implementation contracts retain realization. These are authorized iterative design inputs; the complete architecture/analysis baseline is not inferred approved.','','Ownership remains FreshFood-API.Controllers, Services, Services.Implements and DTOs, together with FreshFood.Reposistory.Repository, Repository.Implements and Entities. These ownership labels exist only in the catalog/mapping, not in diagram notation. Component labels do not choose a code namespace or implementation language/tooling. Web and Mobile use their own Pages/CallService and Views/ViewModels/Models packages. No new subsystem, persistent status or database table is created by this design.','','## Analysis-to-Design Class Mapping','','| Analysis Class | Design Class / Component | Mapping Rationale |','|---|---|---|']
s+=['| '+' | '.join(r.values())+' |' for r in maprows]
s+=['','Full structured mapping: [CSV](detailed/analysis-to-design-mapping.csv). Interaction responsibility mapping: [CSV](detailed/interaction-to-design-mapping.csv).','','## Detailed Design Class Diagrams','','Each editable master contains multiple pages. Page 1 is the connected VOPC-to-design realization, with source analysis class and applied solution tagged on each classifier. DTO contracts are connected by usage dependencies, and processing/repository classes depend on entity types. Member excerpts keep this complete collaboration view readable. Page 2 shows Web View classes, page 3 Mobile classes, and the subsequent full-detail pages provide complete attributes/operations. Package ownership is traced in a separate mapping; no package is displayed in the diagrams. Later pages show API/controller/service/repository injection, participating entities, request/response contracts and applicable transition classes. Shared types are the same classifier wherever projected; repeated appearances are not separate implementations.','','| Use case / shared concern | Editable master | Pages |','|---|---|---|']
for owner in list(m['scope'])+['shared','transitions']:
 group=[p for p in pages if p['owner']==owner];src=group[0]['source'].replace(chr(92),'/');label=owner+' '+m['scope'][owner]['title'] if owner in m['scope'] else 'Shared DI and transaction adapters' if owner=='shared' else 'All 24 state-transition classes'
 s+=['| '+label+' | ['+Path(src).name+'](../'+src.replace('artifacts/','',1)+') | '+str(len(group))+' |']
s+=['','### Rendered page index','','| Owner | Page | View | PNG |','|---|---|---|---|']
for p in pages:s+=['| '+p['owner']+' | '+str(p['page'])+' | '+p['title']+' | [PNG](../'+p['image'].replace('artifacts/','',1)+') |']
s+=['','## Detailed Class Specifications','','[Full class specifications](detailed/class-specifications.md) contain all '+str(len(classes))+' classifiers, constructor dependencies, attribute visibility, typed operations and interface realizations. [Machine-readable class model](detailed/detailed-class-model.json) is a generation/verification input; the Draw.io files remain the editable diagram masters.','','View class ownership and backend-only DI correction: [review](detailed/view-layer-consistency.md) / [mapping](detailed/view-layer-class-mapping.csv).','','View package correction and class allocation: [review](detailed/view-layer-consistency.md) / [mapping](detailed/view-layer-class-mapping.csv).','','Runtime and design-solution audit: [review](detailed/architecture-realization-review.md).','','View package correction and class allocation: [review](detailed/view-layer-consistency.md) / [mapping](detailed/view-layer-class-mapping.csv).','','DTO/entity relationship conventions: [review](detailed/dto-entity-relationship-review.md) / [usage mapping](detailed/dto-entity-dependency-mapping.csv).','','## Dependency injection design','','Controllers consume service interfaces. Services consume repository, identity and gateway interfaces. Concrete repository implementations share one scoped IRepositorySession and IUnitOfWork; they do not reference API DTOs, services or controllers. API service implementations map entities to DTOs. The selected backend runtime is Node.js. Backend and Web async contracts use Promise and Node cancellation uses AbortSignal; Mobile uses Future. Typed UML signatures do not select TypeScript, an HTTP framework, a DI container library or a PostgreSQL driver. DTO names in client signatures denote platform-local JSON projections, not imported backend classes. Page classifiers represent React page/component responsibilities. Frontend classes hold concrete collaborators through normal object/module/widget lifecycle; frontend injection constructors, client DI interfaces and client DI registrations are removed.','','ApiCompositionRoot registers service and repository implementations, adapters and IEnumerable<IStateTransition>. Business services never call IServiceProvider/GetService. TransitionExecutor materializes a dictionary keyed by transition ID, rejects duplicate IDs and dispatches through IStateTransition. Transition IDs are source-model IDs, not client-authorized operation names. Constructor injection and runtime authorization solve different problems. Client-visible operations cannot submit a verified-payment callback or trusted guard facts. PaymentNoticeHandler represents the server adapter and calls ICheckoutService; there is no PaymentBoundary-to-CheckoutController dependency.','','[Registration and lifetime matrix](detailed/dependency-injection-registrations.csv). API business services, repository instances, transaction session and transition handlers are scoped together. Stateless configured HttpClient transports are supplied by startup; no lifetime claim about a selected HTTP library/version is imposed. Only backend implementations appear in the DI registration matrix. Frontend associations denote ordinary collaboration; labeled HTTPS associations denote remote communication rather than a server object stored in the client.','','## One class per state transition','','Every one of the 24 existing transitions has a distinct concrete IStateTransition implementation. This is a transition-handler design, rather than one class per state. UC-C01, UC-C03 and UC-C05 have no approved lifecycle state machine; ordinary method calls are not invented as new state transitions. Staff approval, dispatch, returns and financial settlement transitions are shared lifecycle support, not newly invented customer use cases.','','| Transition | Concrete class | Source -> target | Trigger / guard |','|---|---|---|---|']
for r in m['transitions']:s+=['| '+r['id']+' | `'+r['class']+'` | '+r['source']+' -> '+r['target']+' | '+(r['label'].replace('\n','; ') or 'Completion transition')+' |']
s+=['','[Full transition mapping](detailed/state-transition-class-mapping.csv). Completion handlers only finish the fulfillment region. They never write a Final status, delete the order or assert a settled refund. I00 and T01u/T01p represent the common acceptOrder and guarded initial-entry steps: all execute in the same checkout transaction, with exactly one initial branch selected. There is no Pending parent and no PendingUnpaid -> PendingPaid transition.','','### Transaction and concurrency responsibilities','','1. Resolve principal/ownership from trusted server context. Caller IDs and guard facts are never accepted as authority from DTOs.','','2. At checkout, lock all sellable FEFO batches deterministically, validate every requested quantity and calculate original goods/shipping allocations. AcceptOrderTransition, exactly one initial-entry handler and the initial payment write join the existing checkout unit of work; order, lines, reservations and cart clear commit together. A shortage rolls everything back. No backorder is accepted. A pre-acceptance payment reference may be a technical in-memory/correlation token; persistence/provider correlation details need design review and do not create a new order state.','','3. TransitionExecutor.ExecuteAsync starts a unit of work for a standalone transition. ExecuteInCurrentTransactionAsync receives the trusted transaction-local snapshot and joins an already active checkout/cancellation unit of work; it must not start or commit a nested transaction. For existing aggregates, load authoritative records under lock and construct a trusted snapshot. For initial acceptance there is no persisted order yet: CheckoutService supplies the server-prepared checkout snapshot and transient workflow position, and the common accept/selected-entry handlers run in that same transaction. The executor updates only the transaction-local UML workflow position until the chosen initial OrderStatus is persisted. Never try to read a nonexistent initial order as an accepted Pending record. Validate source/event/ownership/guards before applying the handler; pass that snapshot to ExecuteAsync as well as CanExecute. Domain methods also check expected state.','','4. Deduplicate using aggregate ID, event ID AND transition ID, so common accept and initial-entry steps for one event are not mistaken for duplicates. Provider-payment dedup uses the existing channel/provider reference uniqueness. Durable generic transition-event storage/version scheme remains a technical design decision; no unapproved table is added here.','','5. Cancellation rechecks current state under the same order lock as staff progression. Only PendingUnpaid, PendingPaid and Confirmed are eligible; release original reservations exactly once, record the specified audit and commit together. A paid cancellation does not trigger an invented refund policy. Customer audit identity storage is unresolved because the current audit catalog has a staff reference; never impersonate a staff member.','','6. Failed delivery records cause/evidence. ReceiveReturnedOrderTransition requires every original line fully received. Staff inspection/disposition remains separate. Product fault refunds captured goods and shipping; confirmed deliberate refusal refunds goods only and retains paid shipping, or records shipping owed/actually collected directly for unpaid goods. Shipping-only cash never sets goods Paid.','','7. StartEligibleRefundTransition requires captured goods, complete receipt, confirmed applicable cause and no duplicate obligation; quality inspection is not a guard. Persist the refund obligation transactionally before any provider call. Do not keep row locks or a database transaction open during an external payout. A post-commit worker/dispatcher may invoke IPayoutPort with the durable refund idempotency key; scheduling/retry policy is TBD and no outbox table is silently added. UnconfiguredPayoutAdapter blocks outgoing transfer pending provider approval. R03/P03/P04 only apply verified settlement evidence and actual amounts; uncertain results never become completed refunds.','','8. Publish existing UI/staff notifications after commit; a publish failure cannot roll back a committed order. Notification retry/durable-delivery guarantees remain TBD. Re-order uses current stock/prices, not historical batch reservations. Reviews require owned Delivered order, 1-5 rating and one review per order. Default-address changes and active-address deletion guards must be atomic within the existing profile unit of work.','','## Source conflicts and unresolved decisions','','- The old UC-C06 normal step 8 and old UC-C07 cancellation clause still contain Pending, while later stakeholder decisions require two independent initial states. This design follows the explicit stakeholder correction and flags the older clauses for controlled reconciliation; it does not renumber use cases. Old sequence pages are inputs, not approved new design sequences.','','- Mandatory telephone confirmation applies only to first unpaid orders. Later capture on an already accepted PendingUnpaid order does not imply an order-state transition. Late-payment fulfillment handling is TBD.','','- Outgoing refund provider/API, final fault-confirmation authority, product-fault courier compensation payer/rate, partial returns/payments, prepaid cancellation refunds, excess/late payments and retry/reconciliation rules remain TBD. The handler exists where the source model specifies a transition, but unresolved actions are blocked rather than implemented with invented policy.','','- Historical FR aliases and UC-C01.3 reuse remain source traceability issues. Use-case and message IDs are retained. Guest cart session identity is maintained without asserting an authenticated guest.','','- Audit storage for customer cancellation, optimistic version representation and durable transition-event evidence need approved schema mapping. Repository interfaces are proposed design seams, not proof that all signatures already have database implementations. No synthetic code/test-pass claim is made.','','## Review and verification gate','','The project master template was inspected for Analysis-to-Design Class Mapping, Detailed Design Class Diagrams and Detailed Class Specifications. The design checklist d4_Checklist_Design Review.xls was read locally. See [review findings](detailed/design-review.md) and [verification](detailed/design-verification.json).','','The new technical design is submitted for Architect/Technical Lead and stakeholder review. Per AGENTS.md sections 2.1 and 2.6, only after explicit design approval are these new diagrams, mappings and class specifications integrated into Chapter V of Requirements_Analysis_Design_Specification.docx and treated as an implementation baseline. The current master is not silently baselined with unapproved new technical classes. No implementation, database migration or test execution was performed by this task.']
(R/'artifacts/design/detailed-design-class-diagrams.md').write_text('\n'.join(s)+'\n',encoding='utf-8')
