files=['artifacts/diagrams/architecture/high-level-architecture.drawio','artifacts/diagrams/architecture/freshfood-component-diagram.drawio','artifacts/diagrams/architecture/freshfood-package-diagram.drawio','src/FreshFood-API/package.json','src/FreshFood.Reposistory/package.json','artifacts/requirements/customer-use-case-descriptions.md','artifacts/requirements/reviews/order-payment-return-use-case-review.md','artifacts/design/freshfood-package-design.md','artifacts/design/architecture-naming-consistency.md','artifacts/analysis/order-state-traceability.csv','artifacts/analysis/sequence-traceability.csv','artifacts/design/database/physical-schema-catalog.json','templates/Template_Requirements_Analysis_Design_Specification.docx','checklists/d4_Checklist_Design Review.xls']+[str(x.relative_to(R)).replace('\\','/') for x in (R/'artifacts/diagrams/class').glob('*vopc.drawio')]+[str(x.relative_to(R)).replace('\\','/') for x in (R/'artifacts/diagrams/sequence').glob('*sequence.drawio')]
(D/'source-provenance.json').write_text(json.dumps({f:hashlib.sha256((R/f).read_bytes()).hexdigest() for f in files},indent=2))
print('Wrote design specification,',len(maprows),'analysis mappings,',len(inter),'service interactions,',len(regs),'DI registrations and 24 transition mappings')
